</main></div></div><div class="modal-shell" id="zynkoReportPreviewModal" aria-hidden="true"><div class="modal-card zynko-report-modal" role="dialog" aria-modal="true" aria-labelledby="zynkoReportTitle"><div class="modal-head"><div class="modal-title-with-icon"><span class="modal-title-icon"><i class="fa-solid fa-file-pdf"></i></span><span class="modal-title-copy"><b id="zynkoReportTitle">Vista previa de reporte PDF</b><small>Seleccione orientación y tamaño antes de descargar.</small></span></div><button type="button" class="modal-close" aria-label="Cerrar"><i class="fa-solid fa-xmark"></i></button></div><div class="zynko-report-modal-body"><div class="zynko-report-controls"><div class="field"><label for="zynkoReportPaper">Tamaño</label><select id="zynkoReportPaper"><option value="letter">Carta</option><option value="a4">A4</option></select></div><div class="field"><label for="zynkoReportOrientation">Orientación</label><select id="zynkoReportOrientation"><option value="portrait">Vertical</option><option value="landscape">Horizontal</option></select></div></div><iframe id="zynkoReportFrame" title="Vista previa del PDF" loading="lazy"></iframe></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cerrar</button><a id="zynkoReportDownload" href="#" class="primary" download><i class="fa-solid fa-download"></i> Descargar PDF</a></div></div></div>
<script>
(()=>{const modal=document.getElementById('zynkoReportPreviewModal');if(!modal)return;const frame=modal.querySelector('#zynkoReportFrame'),download=modal.querySelector('#zynkoReportDownload'),paper=modal.querySelector('#zynkoReportPaper'),orientation=modal.querySelector('#zynkoReportOrientation');let base='';function update(){if(!base)return;const u=new URL(base,location.href);u.searchParams.set('preview','1');u.searchParams.set('paper',paper.value);u.searchParams.set('orientation',orientation.value);frame.src=u.toString();u.searchParams.delete('preview');download.href=u.toString()};document.addEventListener('click',e=>{const btn=e.target.closest('.zynko-report-preview-open');if(!btn)return;e.preventDefault();base=btn.dataset.reportUrl||btn.getAttribute('href');update();modal.classList.add('open');document.body.classList.add('modal-open');modal.setAttribute('aria-hidden','false')});for(const c of [paper,orientation])c.addEventListener('change',update);modal.querySelectorAll('.modal-close').forEach(b=>b.addEventListener('click',()=>{modal.classList.remove('open');document.body.classList.remove('modal-open');modal.setAttribute('aria-hidden','true');frame.src='about:blank'}));})();
</script>
<div class="modal-shell" id="zynkoExcelOptionsModal" aria-hidden="true"><div class="modal-card zynko-excel-modal" role="dialog" aria-modal="true" aria-labelledby="zynkoExcelModalTitle"><div class="modal-head"><div class="modal-title-with-icon"><span class="modal-title-icon"><i class="fa-solid fa-file-excel"></i></span><span class="modal-title-copy"><b id="zynkoExcelModalTitle">Configurar exportación Excel</b><small>Personalice el reporte antes de descargar el archivo XLSX.</small></span></div><button type="button" class="modal-close" aria-label="Cerrar"><i class="fa-solid fa-xmark"></i></button></div><div class="zynko-excel-modal-body"><div class="field"><label for="zynkoExcelTitle">Título del reporte (opcional)</label><input id="zynkoExcelTitle" maxlength="130" placeholder="Utilizar título predeterminado" autocomplete="off"/></div><div class="zynko-excel-modal-grid"><div class="field"><label for="zynkoExcelPaper">Tamaño de página para impresión</label><select id="zynkoExcelPaper"><option value="letter">Carta</option><option value="a4">A4</option></select></div><div class="field"><label for="zynkoExcelOrientation">Orientación de impresión</label><select id="zynkoExcelOrientation"><option value="landscape">Horizontal</option><option value="portrait">Vertical</option></select></div><div class="field"><label for="zynkoExcelDensity">Altura de filas</label><select id="zynkoExcelDensity"><option value="comfortable">Cómoda</option><option value="compact">Compacta</option></select></div><div class="field"><label class="zynko-excel-protection"><input type="checkbox" id="zynkoExcelProtected" checked/><span class="zynko-excel-protection-indicator"><i class="fa-solid fa-check"></i></span><span>Proteger hoja de Excel <small>Activado por defecto. Evita modificaciones accidentales; no cifra el archivo.</small></span></label></div><div class="field"><label>Información del archivo</label><div class="zynko-excel-summary"><i class="fa-solid fa-circle-info"></i> Incluye fecha, hora, usuario que descarga, encabezado, numeración de páginas y filtros.</div></div></div></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button id="zynkoExcelGenerate" type="button" class="primary"><i class="fa-solid fa-file-arrow-down"></i> Descargar Excel</button></div></div></div>
<script>
(()=>{const m=document.getElementById('zynkoExcelOptionsModal');if(!m)return;let base='';const title=m.querySelector('#zynkoExcelTitle'),paper=m.querySelector('#zynkoExcelPaper'),orientation=m.querySelector('#zynkoExcelOrientation'),density=m.querySelector('#zynkoExcelDensity'),protectedBox=m.querySelector('#zynkoExcelProtected');function close(){m.classList.remove('open');m.setAttribute('aria-hidden','true');if(!document.querySelector('.modal-shell.open'))document.body.classList.remove('modal-open')};document.addEventListener('click',e=>{const a=e.target.closest('a[href*="_export_excel"],a[href*="plans_export"],a[href*="plans_export_excel"]');if(!a)return;const u=new URL(a.href,location.href);if(!(/(?:^|_)(?:export|plans_export)(?:_excel)?$/.test(u.searchParams.get('action')||'')&&u.searchParams.get('action')?.includes('excel')||['plans_export','plans_export_excel'].includes(u.searchParams.get('action'))))return;e.preventDefault();base=a.getAttribute('data-export-base')||a.href;title.value='';paper.value='letter';orientation.value='landscape';density.value='comfortable';protectedBox.checked=true;m.classList.add('open');m.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')},true);m.querySelectorAll('.modal-close').forEach(b=>b.addEventListener('click',close));m.addEventListener('click',e=>{if(e.target===m)close()});m.querySelector('#zynkoExcelGenerate').addEventListener('click',()=>{if(!base)return;const u=new URL(base,location.href);if(title.value.trim())u.searchParams.set('excel_title',title.value.trim());u.searchParams.set('excel_paper',paper.value);u.searchParams.set('excel_orientation',orientation.value);u.searchParams.set('excel_density',density.value);u.searchParams.set('excel_protected',protectedBox.checked?'1':'0');const a=document.createElement('a');a.href=u.toString();a.style.display='none';document.body.append(a);a.click();a.remove();close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&m.classList.contains('open'))close()});})();
</script>
